package org.brightstats.desktop;
import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import javafx.stage.Window;
import org.brightstats.stats.PlsSem;

final class ConstructDialog {
    record Settings(String name,int[] columns,PlsSem.Mode mode,double[] weights,PlsSem.MeasurementType measurement){Settings{columns=columns.clone();weights=weights==null?null:weights.clone();}@Override public int[] columns(){return columns.clone();}@Override public double[] weights(){return weights==null?null:weights.clone();}}
    private final Dialog<Settings> dialog=new Dialog<>();private final TextField name=new TextField(),weights=new TextField();private final ComboBox<PlsSem.Mode> mode=new ComboBox<>();private final ComboBox<PlsSem.MeasurementType> measurement=new ComboBox<>();private final ListView<String> indicators=new ListView<>();private final Label error=new Label();private Settings result;
    ConstructDialog(Window owner,List<String> columns,Set<String> otherNames,Settings previous){dialog.initOwner(owner);dialog.setTitle(previous==null?"Add construct":"Edit construct");mode.getItems().setAll(PlsSem.Mode.values());measurement.getItems().setAll(PlsSem.MeasurementType.values());mode.setValue(previous==null?PlsSem.Mode.A:previous.mode());measurement.setValue(previous==null?PlsSem.MeasurementType.REFLECTIVE:previous.measurement());indicators.getItems().setAll(columns);indicators.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);indicators.setPrefHeight(240);weights.setPromptText("Blank uses ones; otherwise one comma-separated weight per selected indicator");if(previous!=null){name.setText(previous.name());for(int column:previous.columns())indicators.getSelectionModel().select(column);if(previous.weights()!=null)weights.setText(Arrays.toString(previous.weights()).replaceAll("[\\[\\]]",""));}else mode.valueProperty().addListener((property,old,value)->measurement.setValue(value==PlsSem.Mode.A?PlsSem.MeasurementType.REFLECTIVE:PlsSem.MeasurementType.FORMATIVE));Label help=UiAppearance.label("Measurement type and weight-estimation mode are separate properties. Select indicators using Ctrl or Shift. Initial weights follow the selected indicators in dataset-column order; negative weights are allowed, but the whole vector cannot be zero.");help.setWrapText(true);error.setWrapText(true);VBox content=new VBox(8,UiAppearance.label("Construct name"),name,UiAppearance.label("Measurement type"),measurement,UiAppearance.label("Weighting mode"),mode,UiAppearance.label("Indicators"),indicators,UiAppearance.label("Initial weights"),weights,help,error);content.setPadding(new Insets(12));dialog.getDialogPane().setContent(content);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);dialog.setResizable(true);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{result=null;try{String selectedName=name.getText().trim();if(selectedName.isEmpty()||selectedName.length()>256||otherNames.contains(selectedName))throw new IllegalArgumentException("Choose a unique construct name of 1–256 characters.");int[] selected=indicators.getSelectionModel().getSelectedIndices().stream().mapToInt(Integer::intValue).toArray();if(selected.length==0)throw new IllegalArgumentException("Select at least one indicator.");double[] initial=null;if(!weights.getText().isBlank()){initial=Arrays.stream(weights.getText().trim().split("[,\\s]+")).mapToDouble(Double::parseDouble).toArray();if(initial.length!=selected.length)throw new IllegalArgumentException("Enter one initial weight per selected indicator.");double norm=0;for(double value:initial){if(!Double.isFinite(value))throw new IllegalArgumentException("Initial weights must be finite.");norm=Math.hypot(norm,value);}if(norm==0)throw new IllegalArgumentException("Initial weights cannot all be zero.");}new PlsSem.Block(selectedName,selected,mode.getValue(),initial,measurement.getValue());result=new Settings(selectedName,selected,mode.getValue(),initial,measurement.getValue());}catch(Exception problem){event.consume();error.setText(problem.getMessage());}});dialog.setResultConverter(button->button==ButtonType.OK?result:null);}
    static Optional<Settings> show(Window owner,List<String> columns,Set<String> otherNames,Settings previous){return new ConstructDialog(owner,columns,otherNames,previous).dialog.showAndWait();}
    static Settings smokeTest(Window owner,List<String> columns){var test=new ConstructDialog(owner,columns,Set.of("Taken"),null);test.dialog.show();test.name.setText("Taken");test.indicators.getSelectionModel().select(0);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Duplicate construct name accepted");test.name.setText("Edited α");test.weights.setText("NaN");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Nonfinite initial weight accepted");test.weights.setText("0");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("All-zero initial weights accepted");test.weights.setText("-1");test.mode.setValue(PlsSem.Mode.B);test.measurement.setValue(PlsSem.MeasurementType.REFLECTIVE);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();Settings value=test.dialog.getResult();if(value==null||value.weights()[0]!=-1||value.mode()!=PlsSem.Mode.B||value.measurement()!=PlsSem.MeasurementType.REFLECTIVE)throw new AssertionError("Construct properties changed");return value;}
}
